	"SORT_NUMBER" NUMBER DEFAULT 0,                                                                                                                                                                            
	"REMARK" NVARCHAR2(256),                                                                                                                                                                                   
	"DEL_FLAG" NUMBER DEFAULT 0,                                                                                                                                                                               
	"TENANT_ID" NUMBER NOT NULL ENABLE,                                                                                                                                                                        
	"CREATED_BY" NVARCHAR2(256),                                                                                                                                                                               
	"CREATED_DATE" DATE,                                                                                                                                                                                       
	"UPDATED_BY" NVARCHAR2(256),                                                                                                                                                                               
	"UPDATED_DATE" DATE,                                                                                                                                                                                       
	"PARENT_ID" NUMBER,                                                                                                                                                                                        
